	// byte-compatible with the pre-workspace contract.
	if result.ID != "conversation-session:s" || result.Abstract.Overview.EvidenceIDs[0] != "conversation:e" {
		t.Fatalf("qualification mutated single-repo value: %+v", result)
	}
}

